  assign io_csr_in_mcause_bits =
    io_fault_manager_valid
      ? io_fault_manager_bits_mcause
      : {27'h0,
         _ignore_T_3 & _io_csr_in_fault_T
           ? 5'hB
           : _ignore_T_3 & _io_csr_in_mcause_bits_T_4
               ? 5'h8
               : _ignore_T_2 ? 5'h3 : usageFault ? 5'h19 : 5'h0};
