module Sram_2048x128(
  input          clock,
  input          enable,
  input          write,
  input  [10:0]   addr,
  input  [127:0] wdata,
  input  [15:0] wmask,
  output [127:0] rdata
);

///////////////////////////
///// SRAM Selection //////
///////////////////////////
`ifdef USE_TSMC12FFC
///////////////////////////
///// TSMC12FFC SRAM //////
///////////////////////////
    wire [127:0] nwmask;
    genvar i;
    generate
      for (i = 0; i < 16; i++) begin
        assign nwmask[8*i +: 8] = {8{~wmask[i]}};
      end
    endgenerate
    TS1N12FFCLLMBLVTD2048X128M4SWBSHO u_12ffcp_sram
    (
      // Mode Control
      .BIST(1'b0),          // Built-In Self-Test (active high)
      // Normal Mode Input
      .SLP(1'b0),           // Sleep
      .DSLP(1'b0),          // Deep Sleep
      .SD(1'b0),            // Shut Down
      .CLK(clock),          // Clock
      .CEB(~enable),        // Chip Enable Bar (active low en)
      .WEB(~write),         // Write Enable Bar (active low WE)
      .A(addr),             // Address                               (input [10:0] DM)
      .D(wdata),            // Data                                  (input [127:0] DM)
      .BWEB(nwmask),        // Bit Write Enable Bar (active low BW)  (input [127:0])


      // BIST Mode Input
      .CEBM(1'b0),          // Chip Enable Bar for BIST Mode
      .WEBM(1'b0),          // Write Enable Bar for BIST Mode
      .AM(11'b0),           // Address for BIST Mode               (input [10:0])
      .DM(128'b0),          // Data Input for BIST Mode            (input [127:0] DM)
      .BWEBM({128{1'b1}}),  // Bit Write Enable Bar for BIST Mode  (input [127:0] DM)

      // Data Output
      .Q(rdata),            // Data Output                          (output [127:0])
      .PUDELAY(),           // Power-Up Delay - Connect for tuning timing in late stage design

      // Test Mode
`ifndef SIMULATION
      .RTSEL(2'b0),         // Read Test Select                (input [1:0])
      .WTSEL(2'b0)          // Write Test Select               (input [1:0])
`else
      .RTSEL(2'b1),         // Read Test Select                (input [1:0])
      .WTSEL(2'b1)          // Write Test Select               (input [1:0])
`endif
     );
`elsif USE_GF22
///////////////////////////
//////// GF22 SRAM ////////
///////////////////////////
    wire [127:0] nwmask;
    genvar i;
    generate
      for (i = 0; i < 16; i++) begin
        assign nwmask[8*i +: 8] = {8{wmask[i]}};
      end
    endgenerate

    sasdulssd8LOW1p2048x128m4b2w0c0p0d0l0rm3sdrw01 u_gf22_sram (
      // Data Output
      .Q(rdata),            // Data Output [127:0]
      // Data Input
      .ADR(addr),           // Address [10:0]
      .D(wdata),            // Data Input [127:0]
      .WEM(nwmask),         // Write Enable Mask [127:0] (active high)
      .WE(write),           // Write Enable (active high)
      .ME(enable),          // Memory Enable (active high)
      .CLK(clock),          // Clock
      // Test and Power-saving pins - tied off
      .TEST1(1'b0),
      .TEST_RNM(1'b0),
      .RME(1'b0),
      .RM(4'b0),
      .WA(2'b0),
      .WPULSE(3'b0),
      .LS(1'b0),
      .BC0(1'b0),
      .BC1(1'b0),
      .BC2(1'b0)
    );
`else
///////////////////////////
////// Generic SRAM ///////
///////////////////////////
  reg [127:0] mem [0:2047];
  reg [10:0] raddr;

  assign rdata = mem[raddr];

`ifndef SYNTHESIS
  task randomMemoryAll;
  for (int i = 0; i < 2048; i++) begin
    // $random returns a 32-bit value, so four are concatenated to fill the 128-bit register.
    mem[i] = { $random, $random, $random, $random };
  end
  endtask

  initial begin
    randomMemoryAll;
  end
`endif

  always @(posedge clock) begin
    for (int i = 0; i < 16; i++) begin
      if (enable & write & wmask[i]) begin
        mem[addr][i*8 +: 8] <= wdata[8*i +: 8];
      end
    end

    if (enable & ~write) begin
      raddr <= addr;
    end
  end
`endif // FFCP12_SRAM

endmodule

// ==========================================================================
// VRF Shadow Module - Populates tb_top.vecregfile by probing hardware VRF
// ==========================================================================
// Uses SystemVerilog bind to inject into tb_top and connect vecregfile
// directly to the hardware VRF via hierarchical reference.
// The tracer uses vecregfile for vector instruction results reporting.
// ==========================================================================
module vrf_shadow_probe (
    input  logic        clk,
    input  logic        resetn,
    output logic [127:0] vecregfile [0:31]
);
    // Directly probe the hardware VRF via hierarchical reference.
    // Path: tb_top -> dut (RvvCoreMiniVerificationAxi)
    //   -> core (RvvCoreMiniVerification)
    //   -> rvvCore (RvvCoreShim)
    //   -> rvvCoreWrapper (RvvCoreWrapper)
    //   -> core (RvvCore)
    //   -> backend (rvv_backend)
    //   -> u_vrf (rvv_backend_vrf)
    //   -> vrf_reg (rvv_backend_vrf_reg)
    //   -> vreg [NUM_VRF-1:0][VLEN-1:0]
    //
    // Continuously mirror the hardware VRF into vecregfile.
    // The tracer delays retirement signals by 1 cycle, then reads vecregfile.
    // With always_comb, vecregfile always reflects the current VRF state.
    always_comb begin
        for (int i = 0; i < 32; i++) begin
            vecregfile[i] = dut.core.rvvCore.rvvCoreWrapper.core.backend.u_vrf.vrf_reg.vreg[i];
        end
    end
endmodule

// Bind vrf_shadow_probe into tb_top to populate vecregfile
/* verilator lint_off MULTIDRIVEN */
bind tb_top vrf_shadow_probe vrf_shadow_inst (
    .clk        (clk),
    .resetn     (resetn),
    .vecregfile (vecregfile)
);
/* verilator lint_on MULTIDRIVEN */
